-- Feed da Base: o nível "estado" vira "região imediata" (decisões de 15/10).
--
-- Primeiro trocamos estado por cidade, mas aí quem mora em São José dos
-- Pinhais não via post de Curitiba, que fica a 15 min. A região geográfica
-- imediata do IBGE resolve isso: junta cada cidade com as vizinhas que
-- dependem dela (Curitiba, SJP, Pinhais, Colombo, Araucária...), cobre todos
-- os municípios e cada região fica dentro de uma UF só.
--
-- Os níveis ficam bairro, região imediata, região (Sul, Sudeste...) e Brasil.
-- Moderação igual: fora do bairro só admin aprova, e a auto-aprovação de 2h
-- continua só para bairro. As Ações usam a mesma tabela para o filtro.
--
-- Não havia post de estado em produção quando isto foi escrito; se houver,
-- vira de região imediata, que circula para menos gente.
--
-- Os dados de `municipios` saem de scripts/gen-municipios.py (API do IBGE).

create table if not exists municipios (
  ibge        int primary key,
  nome        text not null,
  uf          text not null,
  regiao_id   int not null,
  regiao_nome text not null
);

-- Dado geográfico público: quem está logado lê (o app monta o rótulo e o
-- filtro das ações). Anônimo não precisa.
alter table municipios enable row level security;
revoke all on municipios from public, anon, authenticated;
grant select on municipios to authenticated;
drop policy if exists municipios_read on municipios;
create policy municipios_read on municipios for select to authenticated using (true);

/**
 * Nome de cidade comparável: sem acento, sem apóstrofo nem hífen, minúsculo.
 * O CEP (ViaCEP) e o IBGE às vezes escrevem diferente ("D'Oeste", "d'Oeste").
 */
create or replace function public.norm_city(t text) returns text
language sql immutable set search_path = public as $$
  select btrim(regexp_replace(lower(translate(coalesce(t, ''),
    'ÁÀÂÃÄáàâãäÉÈÊËéèêëÍÌÎÏíìîïÓÒÔÕÖóòôõöÚÙÛÜúùûüÇçÑñ''’`´-',
    'AAAAAaaaaaEEEEeeeeIIIIiiiiOOOOOoooooUUUUuuuuCcNn     ')), '\s+', ' ', 'g'));
$$;

create index if not exists idx_municipios_nome on municipios (uf, public.norm_city(nome));

/** Região imediata de uma cidade (null se o nome não bate com o IBGE). */
create or replace function public.region_of_city(p_city text, p_uf text) returns int
language sql stable security definer set search_path = public as $$
  select regiao_id from municipios
   where uf = p_uf and public.norm_city(nome) = public.norm_city(p_city)
   limit 1;
$$;

/**
 * Duas cidades estão na mesma região imediata? Se alguma não for achada na
 * tabela, cai na comparação da própria cidade, para nunca abrir demais.
 */
create or replace function public.same_region(p_city1 text, p_uf1 text, p_city2 text, p_uf2 text)
returns boolean
language sql stable security definer set search_path = public as $$
  select case
    when p_uf1 is distinct from p_uf2 then false
    when r1 is not null and r2 is not null then r1 = r2
    else public.norm_city(p_city1) = public.norm_city(p_city2)
  end
  from (select public.region_of_city(p_city1, p_uf1) r1, public.region_of_city(p_city2, p_uf2) r2) x;
$$;

/** Região imediata de quem está logado, com as cidades dela (rótulo e filtros do app). */
create or replace function public.my_region()
returns table (regiao_id int, regiao_nome text, uf text, cidades text[])
language sql stable security definer set search_path = public as $$
  select m.regiao_id, m.regiao_nome, m.uf,
         (select array_agg(c.nome order by c.nome) from municipios c where c.regiao_id = m.regiao_id)
    from profiles p
    join municipios m on m.uf = p.state and public.norm_city(m.nome) = public.norm_city(p.city)
   where p.id = auth.uid()
   limit 1;
$$;

revoke execute on function public.region_of_city(text, text)            from public, anon;
revoke execute on function public.same_region(text, text, text, text)   from public, anon;
revoke execute on function public.my_region()                           from public, anon;
grant execute on function public.region_of_city(text, text)             to authenticated;
grant execute on function public.same_region(text, text, text, text)    to authenticated;
grant execute on function public.my_region()                            to authenticated;

-- --------------------------------------------------------------- feed

alter table posts drop constraint if exists posts_scope_check;
update posts set scope = 'regiao_imediata' where scope in ('estado', 'cidade');
alter table posts add constraint posts_scope_check
  check (scope in ('bairro', 'regiao_imediata', 'regiao', 'brasil'));

drop policy if exists posts_select_feed on posts;
create policy posts_select_feed on posts
  for select using (
    status = 'published'
    and public.is_militant_or_above()
    and (
      (scope = 'bairro' and (neighborhood, city) = (select neighborhood, city from public.my_area()))
      or (scope = 'regiao_imediata'
          and public.same_region(city, state, (select city from public.my_area()), public.my_state()))
      or (scope = 'regiao' and public.region_of(state) = public.region_of(public.my_state()))
      or scope = 'brasil'
    )
  );

